#include <webcpp/asio/steady_timer.hpp>
#include <webcpp/cobalt/main.hpp>
#include <webcpp/cobalt/op.hpp>

using namespace boost;

// tag::timer_example[]
struct wait_op final : webcpp::cobalt::op<system::error_code>  // <1>
{
    webcpp::asio::steady_timer& tim;

    wait_op(webcpp::asio::steady_timer& tim) : tim(tim) {}

    void ready(webcpp::cobalt::handler<system::error_code> h) override  // <2>
    {
        if (tim.expiry() < std::chrono::steady_clock::now())
            h(system::error_code{});
    }

    void initiate(webcpp::cobalt::completion_handler<system::error_code> complete) override  // <3>
    {
        tim.async_wait(std::move(complete));
    }
};

webcpp::cobalt::main co_main(int argc, char* argv[]) {
    webcpp::asio::steady_timer tim{co_await webcpp::asio::this_coro::executor,
                                   std::chrono::milliseconds(std::stoi(argv[1]))};
    co_await wait_op(tim);  // <4>
    co_return 0;            //
}

// end::timer_example[]
